⌈log2⌉2*n≡1+⌈log2⌉n : ∀ n {acc acc'} .{{_ : NonZero n}} → ⌈log2⌉ (2 * n) acc ≡ 1 + ⌈log2⌉ n acc'
1 clause(s), 4 step(s), lemmas: (none)

clause ⌈log2⌉2*n≡1+⌈log2⌉n (suc n)
  goal: ⌈log2⌉ (2 * suc n) acc₁ ≡ 1 + ⌈log2⌉ (suc n) acc'
  (where-block not taken apart)
  1. ⌈log2⌉ (suc (n + suc (n + zero))) _ ≡ ⌈log2⌉ (suc (n + suc n)) (<-wellFounded _)
       by {!!}
  2. ⌈log2⌉ (suc (n + suc n)) (<-wellFounded _) ≡ ⌈log2⌉ (suc (suc n + n)) (<-wellFounded _)
       by {!!}
  3. ⌈log2⌉ (suc (suc n + n)) (<-wellFounded _) ≡ suc {!!}
       by {!!}
  4. suc {!!} ≡ 1 + ⌈log2⌉ (suc n) _
       by {!!}
